// === Tab: let out of control ===
function setup(){
 createCanvas(800, 800);
 background(0);
 noStroke(); 

}
 let th = 0;
 let offset = 0;

function draw(){
  background(1);
  fill(255);
  text(offset + "", 20, 20);
  translate(width/2, height/2);
  stroke(255);



  for(i = 0; i < 500; i++){
   rotate(-1 * 2 * PI * offset);

   fill(255);
   stroke(255);
   ellipse(i, 0, 7.5, 7.5);

   //line(i, 0, 0, 0);
   /*
   fill(255, 10);
   noStroke();

   ellipse(i/2, 0, 50, 50);
   */
  }
  if(!keyPressed){
    offset += 0.00001;
  }

}

function keyPressed(){
  if(keyCode == RIGHT){
    offset += .001; 
  }
  if(keyCode == LEFT){
     offset -= .0001; 
  }
  if(keyCode == DOWN)
    offset += 0;
}

